model_config.built_in_css:
/* ===== 全局基础 ===== */
* {
  box-sizing: border-box;
}

body, .ry-wrap, .bet-wrap, .lq-wrap, .details-status pre, .actions .item {
  font-size: 16px !important;
  line-height: 2 !important;
}

/* ===== 正文区域 ===== */
.details-cot pre,
.details-scene pre,
.details-status pre,
.details-mem pre,
.actions .item,
.env,
.bet-body,
.lq-body,
.ry-text,
.txt-su,
.txt-su-break,
.txt-n,
.txt-n-break {
  font-size: 16px !important;
  line-height: 2.2 !important;
  color: #d0d0d8 !important;
}

/* ===== 折叠面板统一间距 ===== */
.details-cot,
.details-scene,
.details-status,
.details-mem,
.details-player {
  margin-bottom: 8px !important;
  padding: 0 !important;
}

.details-cot summary,
.details-scene summary,
.details-status summary,
.details-mem summary,
.details-player summary {
  padding: 8px 14px !important;
  font-size: 15px !important;
  letter-spacing: 1.5px !important;
}

.details-cot pre,
.details-scene pre,
.details-status pre,
.details-mem pre,
.details-player pre {
  padding: 8px 14px !important;
  margin: 4px 0 !important;
  font-size: 15px !important;
  line-height: 1.9 !important;
}

/* 环境描写紧凑 */
.env {
  padding: 8px 0 !important;
  margin: 6px 0 10px 0 !important;
  font-size: 14px !important;
}

/* 正文紧凑 */
.bet-body,
.lq-body,
.ry-text {
  margin: 8px 0 !important;
}

/* 行动选项紧凑 */
.actions {
  padding: 14px 18px !important;
  margin: 10px 0 !important;
}

.actions .title {
  font-size: 16px !important;
  margin-bottom: 8px !important;
  padding-bottom: 6px !important;
}

.actions .item {
  padding: 6px 0 !important;
  font-size: 15px !important;
  line-height: 1.9 !important;
}

/* 分隔线紧凑 */
.cut {
  margin: 14px 0 !important;
}

/* =========================================================
   【状态栏 - 冰蓝权力 · 压迫氛围】
   ========================================================= */
.details-status {
  background: rgba(14, 18, 24, 0.92) !important;
  border: 2px solid rgba(160, 192, 224, 0.30) !important;
  border-radius: 10px !important;
  margin-bottom: 8px !important;
  padding: 2px !important;
  box-shadow: 0 2px 20px rgba(100, 160, 220, 0.06) !important;
}

.details-status summary {
  color: #a0c0e0 !important;
  background: rgba(160, 192, 224, 0.08) !important;
  border-radius: 8px !important;
  padding: 10px 16px !important;
  font-size: 16px !important;
  font-weight: 700 !important;
  letter-spacing: 2px !important;
  cursor: pointer !important;
  user-select: none !important;
  border-bottom: 1px solid rgba(160, 192, 224, 0.12) !important;
}

.details-status summary:hover {
  background: rgba(160, 192, 224, 0.14) !important;
}

.details-status pre {
  background: rgba(8, 10, 14, 0.7) !important;
  color: #d0d0d8 !important;
  border-radius: 6px !important;
  padding: 10px 14px !important;
  font-size: 16px !important;
  line-height: 2.0 !important;
  margin: 6px 4px !important;
  border: 1px solid rgba(160, 192, 224, 0.08) !important;
  font-family: 'Microsoft YaHei', 'PingFang SC', sans-serif !important;
  white-space: pre-wrap !important;
  word-wrap: break-word !important;
  word-break: break-word !important;
  overflow-wrap: break-word !important;
}

.details-status pre,
.details-status pre * {
  color: #d0d0d8 !important;
  font-size: 16px !important;
  font-weight: 400 !important;
}

.details-status pre .highlight {
  color: #c87888 !important;
  font-weight: 600 !important;
}

.details-status pre .label {
  color: #6a7080 !important;
  font-weight: 300 !important;
}

/* ===== 思维链/场景/记忆区统一紧凑 ===== */
.details-cot {
  background: rgba(20, 24, 32, 0.5) !important;
  border: 1px dashed #1c2030 !important;
  border-radius: 8px !important;
  margin-bottom: 8px !important;
}

.details-cot summary {
  padding: 8px 14px !important;
  color: #6a7080 !important;
  font-size: 15px !important;
  letter-spacing: 2px !important;
  font-weight: 600 !important;
}

.details-cot[open] summary {
  border-bottom: 1px dashed #1c2030 !important;
  margin-bottom: 4px !important;
}

.details-cot pre {
  margin: 4px 0 !important;
  padding: 6px 14px !important;
  font-size: 14px !important;
  line-height: 1.8 !important;
  color: #a0a8b8 !important;
}

/* 场景折叠 */
.details-scene {
  background: rgba(20, 24, 32, 0.4) !important;
  border: 1px solid #1c2030 !important;
  border-radius: 8px !important;
  margin-bottom: 8px !important;
}

.details-scene summary {
  padding: 8px 14px !important;
  color: #a0c0e0 !important;
  font-size: 15px !important;
  letter-spacing: 2px !important;
  font-weight: 600 !important;
}

.details-scene[open] summary {
  border-bottom: 1px solid #1c2030 !important;
  margin-bottom: 4px !important;
}

.details-scene pre {
  margin: 4px 0 !important;
  padding: 6px 14px !important;
  font-size: 14px !important;
  line-height: 1.8 !important;
  color: #a0a8b8 !important;
}

/* 记忆区 */
.details-mem {
  background: rgba(20, 24, 32, 0.4) !important;
  border: 1px solid #1c2030 !important;
  border-radius: 8px !important;
  margin-bottom: 8px !important;
}

.details-mem summary {
  padding: 8px 14px !important;
  color: #a0c0e0 !important;
  font-size: 15px !important;
  letter-spacing: 2px !important;
  font-weight: 600 !important;
}

.details-mem[open] summary {
  border-bottom: 1px solid #1c2030 !important;
  margin-bottom: 4px !important;
}

.details-mem pre {
  margin: 4px 0 !important;
  padding: 6px 14px !important;
  font-size: 14px !important;
  line-height: 1.8 !important;
  color: #a0a8b8 !important;
}

/* 玩家状态 */
.details-player {
  background: rgba(20, 24, 32, 0.5) !important;
  border: 1px solid #1c2030 !important;
  border-radius: 8px !important;
  margin-bottom: 8px !important;
}

.details-player summary {
  padding: 8px 14px !important;
  color: #a0c0e0 !important;
  font-size: 15px !important;
  letter-spacing: 2px !important;
  font-weight: 600 !important;
}

.details-player[open] summary {
  border-bottom: 1px solid #1c2030 !important;
  margin-bottom: 4px !important;
}

.details-player pre {
  margin: 4px 0 !important;
  padding: 6px 14px !important;
  font-size: 14px !important;
  line-height: 1.8 !important;
  color: #a0a8b8 !important;
}

/* ===== 选项文字 ===== */
.actions .item,
.bet-acts-i,
.lq-acts-i,
.ry-opt-list {
  font-size: 15px !important;
  line-height: 2.2 !important;
  color: #d0d0d8 !important;
  padding: 6px 0 !important;
}

/* ===== 标题/标签文字 ===== */
.actions .title,
.bet-acts-h,
.lq-acts-h,
.ry-opt-title {
  font-size: 16px !important;
  font-weight: bold !important;
  letter-spacing: 3px !important;
  color: #a0c0e0 !important;
}

/* ===== 环境描写 ===== */
.env {
  font-size: 14px !important;
  color: #6a7080 !important;
  text-align: center;
  padding: 6px 0 !important;
  margin: 4px 0 8px 0 !important;
  letter-spacing: 1.5px !important;
  border-top: 1px solid rgba(160, 192, 224, 0.06);
  border-bottom: 1px solid rgba(160, 192, 224, 0.06);
}

/* ===== 折叠面板内文字 ===== */
details pre,
details .ry-think,
details .lq-mem-in,
details .bet-mem-in {
  font-size: 14px !important;
  line-height: 1.9 !important;
  color: #d0d0d8 !important;
  padding: 6px 12px !important;
  background: rgba(0, 0, 0, 0.25) !important;
  border-radius: 6px !important;
}

/* ===== 输入框和按钮 ===== */
.ryIn, .ryBtn, .ryBtnB, .ryBtnP, .ryGBtn {
  font-size: 15px !important;
  padding: 10px 18px !important;
}

.ryIn {
  color: #d0d0d8 !important;
  background: rgba(8, 10, 14, 0.85) !important;
  border: 1px solid #1c2030 !important;
  border-radius: 10px !important;
}

/* ===== 卡片整体背景 ===== */
.bet-wrap, .ry-wrap, .lq-wrap {
  background: #0a0c10 !important;
  padding: 20px 20px !important;
  border-radius: 14px !important;
  border: 1px solid #1c2030 !important;
}

/* ===== 滚动条美化 ===== */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: #0a0c10;
}
::-webkit-scrollbar-thumb {
  background: #2a3038;
  border-radius: 10px;
}
::-webkit-scrollbar-thumb:hover {
  background: #3a4048;
}

/* ===== 基础样式保留 ===== */
pre{white-space:pre-wrap;word-wrap:break-word;color:inherit;font-size:16px;line-height:1.8;}
details{color:inherit;}
summary{color:inherit;cursor:pointer;user-select:none;font-size:16px;padding:8px 0;}

/* 分隔线 */
.cut{ border:none;height:1px;background:linear-gradient(90deg,transparent,#1c2030,transparent);margin:14px 0; }

/* 对话高亮色 */
.txt-su{color:#a0c0e0 !important;font-weight:600 !important;}
.txt-su-break{color:#c87888 !important;font-style:italic !important;font-weight:600 !important;}

/* 环境描述 */
.env{color:#6a7080;font-size:16px;text-align:center;padding:12px 0;margin-bottom:20px;border-top:1px dashed #1c2030;border-bottom:1px dashed #1c2030;letter-spacing:1.5px;line-height:1.8;}
